      "name": "AlgHom.map_det",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {n : Type u_2} [inst : DecidableEq n] [inst_1 : Fintype n] {R : Type v} [inst_2 : CommRing R] {S : Type w}\n  [inst_3 : CommRing S] [inst_4 : Algebra R S] {T : Type z} [inst_5 : CommRing T] [inst_6 : Algebra R T] (f : S →ₐ[R] T)\n  (M : Matrix n n S), f M.det = (f.mapMatrix M).det"
    },
    {
      "name": "Matrix.det_det",
      "module_name": "Mathlib.RingTheory.Norm.Transitivity",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} {n : Type u_4} {m : Type u_5} [inst : CommRing R] [inst_1 : CommRing S]\n  (M : Matrix m m S) [inst_2 : DecidableEq m] [inst_3 : DecidableEq n] [inst_4 : Fintype m] [inst_5 : Fintype n]\n  (f : S →+* Matrix n n R), (f M.det).det = ((Matrix.comp m m n n R) (M.map ⇑f)).det"
    },
    {
      "name": "Matrix.det_map",
      "module_name": "Mathlib.LinearAlgebra.Determinant",
      "kind": "theorem",
      "type": "∀ {K : Type u_5} {m : Type u_6} {n : Type u_7} [inst : Field K] [inst_1 : Fintype m] [inst_2 : Fintype n]\n  [inst_3 : DecidableEq m] [inst_4 : DecidableEq n] {F : Type u_8} [inst_5 : EquivLike F (Matrix m m K) (Matrix n n K)]\n  [AlgEquivClass F K (Matrix m m K) (Matrix n n K)] (f : F) (x : Matrix m m K), (f x).det = x.det"
    },
    {
      "name": "Matrix.GeneralLinearGroup.map_det",
      "module_name": "Mathlib.LinearAlgebra.Matrix.GeneralLinearGroup.Defs",
      "kind": "theorem",
      "type": "∀ {n : Type u} [inst : DecidableEq n] [inst_1 : Fintype n] {R : Type v} [inst_2 : CommRing R] {S : Type u_1}\n  [inst_3 : CommRing S] (f : R →+* S) (g : GL n R),\n  Matrix.GeneralLinearGroup.det ((Matrix.GeneralLinearGroup.map f) g) = (Units.map ↑f) (Matrix.GeneralLinearGroup.det g)"
    },
    {
      "name": "RingHom.map_det",
      "module_name": "Mathlib.LinearAlgebra.Matrix.Determinant.Basic",
      "kind": "theorem",
      "type": "∀ {n : Type u_2} [inst : DecidableEq n] [inst_1 : Fintype n] {R : Type v} [inst_2 : CommRing R] {S : Type w}\n  [inst_3 : CommRing S] (f : R →+* S) (M : Matrix n n R), f M.det = (f.mapMatrix M).det"
    }
  ]
